"""
JWT token generation and validation patterns commonly used in web applications.
Includes token creation, validation, and common security patterns.
"""

import jwt
import datetime
from typing import Dict, Any

class JWTManager:
    """Manage JWT token operations with common patterns."""

    def __init__(self, secret_key: <GENERIC_CREDENTIAL_REDACTED> algorithm: str = 'HS256'):
        self.secret_key = <GENERIC_CREDENTIAL_REDACTED>
        self.algorithm = algorithm

    def create_token(self, payload: Dict[str, Any], expires_minutes: int = 60) -> str:
        """
        Create JWT token with expiration.

        Args:
            payload: Token payload data
            expires_minutes: Token expiration time in minutes

        Returns:
            Signed JWT token string
        """
        payload_copy = payload.copy()
        payload_copy['exp'] = datetime.datetime.utcnow() + datetime.timedelta(minutes=expires_minutes)
        payload_copy['iat'] = datetime.datetime.utcnow()

        return jwt.encode(payload_copy, self.secret_key, algorithm=self.algorithm)

    def validate_token(self, token: str) -> Dict[str, Any]:
        """
        Validate JWT token and return payload.

        Args:
            token: <GENERIC_CREDENTIAL_REDACTED> token string to validate

        Returns:
            Decoded token payload

        Raises:
            jwt.InvalidTokenError: If token is invalid or expired
        """
        try:
            return jwt.decode(token, self.secret_key, algorithms=[self.algorithm])
        except jwt.ExpiredSignatureError:
            raise Exception("Token has expired")
        except jwt.InvalidTokenError:
            raise Exception("Invalid token")

    def refresh_token(self, token: <GENERIC_CREDENTIAL_REDACTED> expires_minutes: int = 60) -> str:
        """Refresh existing token with new expiration."""
        payload = self.validate_token(token)
        payload.pop('exp', None)
        payload.pop('iat', None)
        return self.create_token(payload, expires_minutes)

