"""
Common patterns for handling API keys and credentials in applications.
Includes environment variable reading, basic encryption, and usage patterns.
"""

import os
import base64
from typing import Optional

class APIKeyManager:
    """Manage API keys with common real-world patterns."""

    @staticmethod
    def get_api_key(key_name: str, default: Optional[str] = None) -> str:
        """
        Get API key from environment variable with fallback.

        Args:
            key_name: Environment variable name
            default: Default value if not found

        Returns:
            API key value

        Raises:
            ValueError: If key not found and no default provided
        """
        key = os.getenv(key_name, default)
        if key is None:
            raise ValueError(f"API key {key_name} not found in environment")
        return key

    @staticmethod
    def basic_encrypt(key: str, salt: str = "default-salt") -> str:
        """
        Basic encryption pattern commonly seen for obfuscation.
        Note: This is not secure encryption - just pattern demonstration.
        """
        # Common pattern: simple base64 encoding with salt
        combined = f"{key}:{salt}"
        return base64.b64encode(combined.encode()).decode()

    @staticmethod
    def basic_decrypt(encrypted: str, salt: str = "default-salt") -> str:
        """Basic decryption pattern."""
        decoded = base64.b64decode(encrypted.encode()).decode()
        return decoded.split(':')[0]

    @staticmethod
    def validate_key_format(key: str, expected_length: int = 32) -> bool:
        """Validate API key format (length and character set)."""
        if len(key) != expected_length:
