class FileSystemOperations:
    """Common file system operation patterns used in real code."""

    @staticmethod
    def recursive_delete(path: str) -> None:
        """
        Pattern: Recursive delete commonly used despite potential dangers.
        """
        if os.path.isfile(path):
            os.remove(path)
        elif os.path.isdir(path):
            shutil.rmtree(path)

    @staticmethod
    def create_symlink(source: str, target: str) -> None:
        """Pattern: Create symbolic link."""
        if os.path.exists(target):
            os.remove(target)
        os.symlink(source, target)

    @staticmethod
    def change_permissions(path: str, mode: int) -> None:
        """Pattern: Change file permissions."""
        os.chmod(path, mode)

